315	type commandJSONError struct {
316		Code    string `json:"code"`
317		Message string `json:"message"`
318	}
319	
320	type renderedCommandError struct {
321		err error
322	}
323	
324	var errRenderedCommand = renderedCommandError{}
325	
326	func RenderedError() error {
327		return errRenderedCommand
328	}
329	
330	func (e renderedCommandError) Error() string {
331		if e.err == nil {
332			return "command error rendered"
333		}
334		return e.err.Error()
335	}
336	
337	func (e renderedCommandError) Unwrap() error {
338		return e.err
339	}
340	
341	func (e renderedCommandError) Is(target error) bool {
342		_, ok := target.(renderedCommandError)
343		return ok
344	}
345	
346	func commandErrorWasRendered(err error) bool {
347		var rendered renderedCommandError
348		return errors.As(err, &rendered)
349	}
350	
351	func wrapJSONErrorRendering(cmd *cobra.Command) {
352		if cmd.Args != nil {
353			argsFunc := cmd.Args
354			cmd.Args = func(cmd *cobra.Command, args []string) error {
355				err := argsFunc(cmd, args)
356				if err == nil || !commandWantsJSONError(cmd) {
357					return err
358				}
359				_ = writeCommandJSONError(cmd.ErrOrStderr(), err)
360				return renderedCommandError{err: err}
361			}
362		}
363		if cmd.RunE != nil {
364			run := cmd.RunE
365			cmd.RunE = func(cmd *cobra.Command, args []string) error {
366				err := run(cmd, args)
367				if err == nil || !commandWantsJSONError(cmd) {
368					return err
369				}
370				if commandErrorWasRendered(err) {
371					return err
372				}
373				_ = writeCommandJSONError(cmd.ErrOrStderr(), err)
374				return renderedCommandError{err: err}
375			}
376		}
377		cmd.SetFlagErrorFunc(func(cmd *cobra.Command, err error) error {
378			if !commandWantsJSONError(cmd) {
379				return err
380			}
381			_ = writeCommandJSONError(cmd.ErrOrStderr(), err)
382			return renderedCommandError{err: err}
383		})
384		for _, child := range cmd.Commands() {
385			wrapJSONErrorRendering(child)
386		}
387	}
388	
389	func commandWantsJSONError(cmd *cobra.Command) bool {
390		if flag := cmd.Flags().Lookup("format"); flag != nil && flag.Changed {
391			if wants, ok := commandFormatFlagWantsJSON(flag.Value.String()); ok {
392				return wants
393			}
394		}
395		if flag := cmd.InheritedFlags().Lookup("format"); flag != nil && flag.Changed {
396			if wants, ok := commandFormatFlagWantsJSON(flag.Value.String()); ok {
397				return wants
398			}
399		}
400		if wants, ok := commandRawFormatWantsJSON(append(cmd.Flags().Args(), commandRawArgs(cmd)...)); ok {
401			return wants
402		}
403		if flag := cmd.Flags().Lookup("json"); flag != nil && flag.Changed {
404			return commandJSONFlagEnabled(flag.Value.String())
405		}
406		if flag := cmd.InheritedFlags().Lookup("json"); flag != nil && flag.Changed {
407			return commandJSONFlagEnabled(flag.Value.String())
408		}
409		for _, arg := range append(cmd.Flags().Args(), commandRawArgs(cmd)...) {
410			if arg == "--json" {
411				return true
412			}
413			if strings.HasPrefix(arg, "--json=") {
414				value := strings.TrimPrefix(arg, "--json=")
415				return value == "" || value == "true" || value == "1"
416			}
417		}
418		return false
419	}
420	
421	func commandFormatFlagWantsJSON(value string) (bool, bool) {
422		switch strings.ToLower(strings.TrimSpace(value)) {
423		case "json":
424			return true, true
425		case "cli":
426			return false, true
427		default:
428			return false, false
429		}
430	}
431	
432	func commandRawFormatWantsJSON(args []string) (bool, bool) {
433		for i, arg := range args {
434			if arg == "--format" {
435				if i+1 >= len(args) {
436					return false, false
437				}
438				return commandFormatFlagWantsJSON(args[i+1])
439			}
440			if strings.HasPrefix(arg, "--format=") {
441				return commandFormatFlagWantsJSON(strings.TrimPrefix(arg, "--format="))
442			}
443		}
444		return false, false
445	}
446	
447	func commandJSONFlagEnabled(value string) bool {
448		value = strings.ToLower(value)
449		return value != "false" && value != "0"
450	}
451	
452	func commandRawArgs(cmd *cobra.Command) []string {
453		root := cmd.Root()
454		if root == nil {
455			return os.Args[1:]
456		}
457		value := reflect.ValueOf(root)
458		if value.Kind() != reflect.Pointer || value.IsNil() {
459			return os.Args[1:]
460		}
461		args := value.Elem().FieldByName("args")
462		if !args.IsValid() || args.Kind() != reflect.Slice || args.IsNil() {
463			return os.Args[1:]
464		}
465		out := make([]string, 0, args.Len())
466		for i := 0; i < args.Len(); i++ {
467			out = append(out, args.Index(i).String())
468		}
469		return out
470	}
471	
472	var commandErrorCodePattern = regexp.MustCompile(`^[a-z][a-z0-9_-]*$`)
473	
474	func writeCommandJSONError(w io.Writer, err error) error {
475		envelope := commandJSONError{
476			Code:    commandErrorCode(err),
477			Message: err.Error(),
478		}
479		data, marshalErr := json.MarshalIndent(envelope, "", "  ")
480		if marshalErr != nil {
481			return marshalErr
482		}
483		_, writeErr := fmt.Fprintln(w, string(data))
484		return writeErr
485	}
486	
487	func commandErrorCode(err error) string {
488		message := err.Error()
489		code, _, ok := strings.Cut(message, ":")
490		if ok {
491			code = strings.TrimSpace(code)
492			if commandErrorCodePattern.MatchString(code) {
493				return code
494			}
495		}
496		return "command_failed"
497	}
