	now := time.Date(2026, 10, 7, 12, 0, 0, 0, time.UTC)
	retracted := hostedSyncTestFact("contested fact", now)
	retracted.Status = factStatusRetracted
	remoteActive := hostedSyncTestFact("contested fact", now)

