	opts, storage, repoDir := hostedSyncHarness(t, fake, true)
	fake.mu.Lock()
	fake.data = encodeFactsNDJSON(t, []factRecord{remoteActive})
	fake.mu.Unlock()
	if err := writeFacts(storage.BrainDir, "main", []factRecord{retracted}); err != nil {
		t.Fatal(err)
	}

