73	// spend tokens — the session is over, nobody is waiting — but it keeps the
74	// rest of the hook contract: stdout stays empty (a one-line summary goes to
75	// stderr), and environment problems (no repo, no brain, no agent on PATH)
76	// are silence, never an error.
77	func newHookSessionEndCommand(opts Options) *cobra.Command {
78		var (
79			sessionID string
80			branch    string
81			agent     string
82			model     string
83			effort    string
