85		cmd := &cobra.Command{
86			Use:   "session-end --session <id>",
87			Short: "Refresh and distill the just-ended session (spends tokens; silent on env problems)",
88			Args:  cobra.NoArgs,
89			RunE: func(cmd *cobra.Command, args []string) error {
