91					return fmt.Errorf("--session <id> is required")
92				}
93				// Paused: skipping loses nothing. The captured session stays
94				// canonical; reconciliation re-exports it after `start`, and the next
95				// gated or manual distill extracts its facts.
96				if memoryWorkerOrigin() || backgroundPaused(opts.Env) {
97					return nil
98				}
99				target := agentSurfaceTarget(opts, nil)
100				repoDir, local, err := resolveLocalTargetRepoDir(cmd.Context(), opts.Runner, target)
101				if err != nil || !local {
102					return nil // no local repo: silence, never an error
103				}
104				perRepo := opts
105				perRepo.Env.RepoRoot = repoDir
106				// Export only changed sessions and publish the short-term overlay so
107				// recall and distill can see the just-ended session immediately. The
108				// durable coordinator performs the heavier long-term consolidation.
109				sub := &cobra.Command{}
110				sub.SetContext(cmd.Context())
111				sub.SetOut(cmd.ErrOrStderr())
112				sub.SetErr(cmd.ErrOrStderr())
113				_, deltaErr := watchShortTermDelta(cmd.Context(), sub, perRepo, repoDir)
114	
