116				// content-free and durable; startup/watch reconciliation or a later
117				// worker pass can repair the missed export without retaining content.
118				storage, storageErr := repoStoragePaths(cmd.Context(), perRepo.Runner, perRepo.Env, repoDir)
119				if storageErr == nil {
120					resolvedBranch := strings.TrimSpace(branch)
121					if resolvedBranch == "" {
122						if current, gitErr := gitScalar(cmd.Context(), perRepo.Runner, repoDir, "branch", "--show-current"); gitErr == nil {
123							resolvedBranch = strings.TrimSpace(current)
124						}
125					}
126					_, warning, hintErr := recordMemoryLifecycleAndLaunch(
127						storage.BrainDir, repoDir, storage.Key, sessionID, resolvedBranch, "session_end", perRepo.Now().UTC(),
128					)
129					if hintErr != nil {
130						fmt.Fprintf(cmd.ErrOrStderr(), "session-end: memory hint failed: %v\n", hintErr)
131					} else if warning != "" {
132						fmt.Fprintf(cmd.ErrOrStderr(), "session-end: %s\n", warning)
133					}
134				}
