136				// session just produced so "which checkpoint changed this symbol"
137				// is answerable immediately. It runs AFTER the durable lifecycle
138				// hint (that must never wait on a slow provider) and independently
139				// of the export result, since it reads git, not transcripts. Never
140				// fails the hook.
141				if entityErr := refreshEntityIndexQuietly(cmd.Context(), perRepo, repoDir); entityErr != nil {
142					fmt.Fprintf(cmd.ErrOrStderr(), "session-end: entity index refresh skipped: %v\n", entityErr)
143				}
