178	func newHookPreEditCommand(opts Options) *cobra.Command {
179		var (
180			file    string
181			branch  string
182			budget  int
183			jsonOut bool
184		)
185		cmd := &cobra.Command{
186			Use:   "pre-edit --file <path>",
187			Short: "Facts locus-anchored to a file about to be edited (silent when none)",
188			Args:  cobra.NoArgs,
189			RunE: func(cmd *cobra.Command, args []string) error {
190				if strings.TrimSpace(file) == "" {
191					return fmt.Errorf("--file is required")
192				}
193				facts, target, ok := hookLoadFacts(cmd, opts, branch)
194				if !ok {
195					return nil // no brain / no facts: silence, never an error
196				}
197				rel := filepath.ToSlash(file)
198				stem := strings.TrimSuffix(filepath.Base(rel), filepath.Ext(rel))
199				// The stem ("distill_cmd") matches facts that name the file without
200				// its extension or talk about its symbols' shared prefix.
