209		cmd.Flags().StringVar(&file, "file", "", "Path of the file about to be edited (repo-relative or absolute)")
210		cmd.Flags().StringVar(&branch, "branch", "", "Branch whose facts to consult (default: current)")
211		cmd.Flags().IntVar(&budget, "budget", hookDefaultBudgetTokens, "Token budget for the emission")
212		cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit JSON instead of text lines")
