21	// hostedFake is an in-memory fact-set head speaking the brainstore wire:
22	// GET …/brain/facts (with the additive authors map), POST …/facts/advance
23	// (CAS: stale oldRef → 412), proposal routes → 404 (v1 cuts them).
24	type hostedFake struct {
25		mu       sync.Mutex
26		ref      string
27		data     []byte
28		authors  map[string]string
29		requests int
30		seq      int
31	}
32	
33	func (f *hostedFake) requestCount() int {
34		f.mu.Lock()
35		defer f.mu.Unlock()
36		return f.requests
37	}
38	
39	func (f *hostedFake) head() []byte {
40		f.mu.Lock()
41		defer f.mu.Unlock()
42		return append([]byte(nil), f.data...)
43	}
44	
45	func newHostedFakeServer(t *testing.T, fake *hostedFake) *httptest.Server {
46		t.Helper()
47		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
48			fake.mu.Lock()
49			defer fake.mu.Unlock()
50			fake.requests++
51			w.Header().Set("Content-Type", "application/json")
52			switch {
53			case strings.Contains(r.URL.Path, "/brain/facts/proposals"):
54				w.WriteHeader(http.StatusNotFound)
55			case r.Method == http.MethodGet && strings.HasSuffix(r.URL.Path, "/brain/facts"):
56				resp := map[string]any{"found": fake.ref != "", "ref": fake.ref, "version": 1, "data": fake.data}
57				if fake.authors != nil {
58					resp["authors"] = fake.authors
59				}
60				_ = json.NewEncoder(w).Encode(resp)
61			case r.Method == http.MethodPost && strings.HasSuffix(r.URL.Path, "/brain/facts/advance"):
62				var body struct {
63					Branch string `json:"branch"`
64					OldRef string `json:"oldRef"`
65					Data   []byte `json:"data"`
66				}
67				if err := json.NewDecoder(r.Body).Decode(&body); err != nil || len(body.Data) == 0 {
68					w.WriteHeader(http.StatusBadRequest)
69					return
70				}
71				if body.OldRef != fake.ref {
72					w.WriteHeader(http.StatusPreconditionFailed)
73					return
74				}
75				fake.seq++
76				fake.ref = fmt.Sprintf("facts-%d", fake.seq)
77				fake.data = body.Data
78				_ = json.NewEncoder(w).Encode(map[string]any{"newRef": fake.ref, "version": fake.seq, "changed": true})
79			default:
80				w.WriteHeader(http.StatusNotFound)
81			}
82		}))
83		t.Cleanup(srv.Close)
84		return srv
85	}
