                      {
                        "text": "entire brain connect",
                        "type": "text",
                        "marks": [
                          {
                            "type": "code",
                            "attrs": {}
                          }
                        ]
                      },
                      {
                        "text": " binds a repo to its hosted brain by storing repo ID, API base URL, and jurisdiction (non-secrets; tokens mint fresh per call). It resolves placement from ",
                        "type": "text"
                      },
                      {
                        "text": "entire repo whereami --json",
                        "type": "text",
                        "marks": [
                          {
                            "type": "code",
                            "attrs": {}
                          }
                        ]
                      },
                      {
                        "text": " or accepts explicit flags, validates URLs, strips ",
                        "type": "text"
                      },
                      {
                        "text": "/api/v1",
                        "type": "text",
                        "marks": [
                          {
                            "type": "code",
                            "attrs": {}
                          }
                        ]
                      },
                      {
                        "text": " suffix (factsync appends it), and performs an initial pull on first connect.",
                        "type": "text"
