		if err != nil {
			fmt.Fprintf(errW, "hosted sync: auto-connect skipped: %v\n", err)
			return nil
		}
	}
	baseURL, err := apiurl.Validate(binding.BaseURL)
	if err != nil {
		fmt.Fprintf(errW, "hosted sync: skipped: %v\n", err)
